function escapeHtml(value) {
  return value.replace(/[&<>"']/g, character => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  })[character]);
}

function renderSessions(state) {
  if (!state || typeof state !== 'object' || Array.isArray(state)) throw new TypeError('invalid state');
  if (state.status === 'loading') return '<p>Loading sessions…</p>';
  if (state.status === 'error') {
    if (typeof state.message !== 'string') throw new TypeError('invalid error message');
    return '<p class="error">' + escapeHtml(state.message) + '</p>';
  }
  if (state.status !== 'ready' || !Array.isArray(state.items)) throw new TypeError('invalid state');
  if (state.items.length === 0) return '<p>No sessions available.</p>';

  const fields = ['id', 'title', 'topic', 'summary', 'room', 'day', 'start', 'end'];
  const ids = new Set();
  return state.items.map(item => {
    if (!item || typeof item !== 'object' || fields.some(field => typeof item[field] !== 'string' || item[field].length === 0)) throw new TypeError('invalid session');
    if (ids.has(item.id)) throw new TypeError('duplicate id');
    ids.add(item.id);
    const value = Object.fromEntries(fields.map(field => [field, field === 'summary' ? item[field] : escapeHtml(item[field])]));
    return '<article data-id="' + value.id + '"><h2>' + value.title + '</h2><p class="topic">' + value.topic + '</p><p>' + value.summary + '</p><p class="place">' + value.room + '</p><time>' + value.day + ' ' + value.start + '–' + value.end + '</time></article>';
  }).join('');
}

module.exports = { renderSessions };

