'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['renderSessions']);
const { renderSessions } = api;

assert.equal(renderSessions({ status: 'loading' }), '<p>Loading sessions…</p>');
assert.equal(renderSessions({ status: 'error', message: 'Unavailable' }), '<p class="error">Unavailable</p>');
assert.equal(
  renderSessions({ status: 'error', message: '<bad> & "quoted" \'single\'' }),
  '<p class="error">&lt;bad&gt; &amp; &quot;quoted&quot; &#39;single&#39;</p>'
);
assert.equal(renderSessions({ status: 'ready', items: [] }), '<p>No sessions available.</p>');

const items = [{
  id: 'a&"\'',
  title: '<Title>',
  topic: 'A & B',
  summary: 'Use "safe" \'HTML\'',
  room: 'R>1',
  day: 'Mon<day',
  start: '09:00',
  end: '10:00'
}, {
  id: 'second',
  title: 'Second',
  topic: 'Topic',
  summary: 'Summary',
  room: 'Room',
  day: 'Tuesday',
  start: '11:00',
  end: '12:00'
}];
const state = { status: 'ready', items };
assert.equal(renderSessions(state),
  '<article data-id="a&amp;&quot;&#39;"><h2>&lt;Title&gt;</h2><p class="topic">A &amp; B</p><p>Use &quot;safe&quot; &#39;HTML&#39;</p><p class="place">R&gt;1</p><time>Mon&lt;day 09:00–10:00</time></article>' +
  '<article data-id="second"><h2>Second</h2><p class="topic">Topic</p><p>Summary</p><p class="place">Room</p><time>Tuesday 11:00–12:00</time></article>'
);
assert.equal(items.length, 2);
assert.equal(items[0].title, '<Title>');
assert.equal(state.status, 'ready');

for (const malformed of [
  null,
  {},
  { status: 'unknown' },
  { status: 'error', message: 7 },
  { status: 'ready', items: null },
  { status: 'ready', items: [{}] },
  { status: 'ready', items: [{ id: '', title: 't', topic: 'x', summary: 's', room: 'r', day: 'd', start: 'a', end: 'b' }] },
  { status: 'ready', items: [{ id: '1', title: 't', topic: 'x', summary: 's', room: 'r', day: 'd', start: 'a', end: 2 }] }
]) assert.throws(() => renderSessions(malformed), TypeError);

const valid = { id: 'dup', title: 'T', topic: 'P', summary: 'S', room: 'R', day: 'D', start: 'A', end: 'E' };
assert.throws(() => renderSessions({ status: 'ready', items: [valid, { ...valid }] }), TypeError);

